function countWords(text) {
  return text.trim().split(/\s+/).filter(Boolean).length;
}

const partOneSpecific = [
  [/home|accommodation/i, /are the transport facilities to your home very good/i, "The bus stop and metro station are both within a short walk of my home, so getting to campus is fairly easy. The only drawback is that buses can be crowded at rush hour. For most daily trips, though, I do not need a car."],
  [/home|accommodation/i, /please describe the room you live in/i, "My room is fairly simple, with a bed, a desk beside the window and a bookshelf for course notes. I keep the desk clear while I am studying, because too many things around me make it harder to focus."],
  [/home|accommodation/i, /what part of your home do you like the most/i, "I like the small study corner beside the window most. It gets good daylight, and I can keep my mathematics books and laptop there. It is not a separate room, but it gives me a quiet place to work."],
  [/home|accommodation/i, /what room does your family spend most of the time in/i, "We spend most of our time in the living room, especially after dinner. Someone might watch the news while the rest of us chat or use our phones. It is the easiest place for everyone to relax together."],
  [/home|accommodation/i, /what makes you feel pleasant in your home/i, "Natural light and a tidy shared space make me feel comfortable at home. I also like having a quiet corner where I can read or work through a problem without being interrupted. It does not need to look perfect."],
  [/home|accommodation/i, /(?:do you think )?it is important to live in a comfortable environment/i, "Yes, especially because home is where people need to rest and recover. A comfortable space does not have to be expensive; enough light, a reasonable amount of quiet and furniture that works well make a noticeable difference."],
  [/home|accommodation/i, /do you live in an apartment or a house/i, "I live in an apartment with my family. It is not very large, but the layout is practical and shops are close by. I like that we can reach public transport on foot, which makes everyday errands simpler."],
  [/home|accommodation/i, /what kind of house or apartment do you want to live in in the future/i, "I would like a bright apartment with a separate study corner and a small balcony. It would be comfortable without being difficult to maintain, and I would want public transport and shops within walking distance."],
  [/home|accommodation/i, /do you prefer living in a house or an apartment/i, "An apartment suits me better at the moment because it is easier to maintain and usually closer to public transport. I would still like a little outdoor space, perhaps a balcony, but I do not need a large house."],
  [/home|accommodation/i, /do you plan to live there for a long time/i, "Probably for the next few years, because it is comfortable and close to the places I need to go. I may move after graduation if work takes me to another city, so I would not make a long-term promise."],
  [/home|accommodation/i, /what.s your favorite room in your apartment or house/i, "My favourite room is the study corner in my bedroom. It is small, but the desk gets natural light and I can keep my course notes nearby. Having a familiar place to work helps me settle down quickly."],
  [/home|accommodation/i, /what kinds of accommodation do you live in/i, "I live in an apartment with my family. It is a practical choice in the city, with enough room for everyone and shops nearby. The building is not luxurious, but it is convenient for daily life."],
  [/home|accommodation/i, /what.s the difference between where you are living now and where you have lived in the past/i, "My current apartment is closer to public transport and gives me a quieter place to study. The home I lived in as a child was more spacious, but it was farther from the city centre and daily services."],
  [/home|accommodation/i, /can you describe the place where you live/i, "I live in a practical apartment with my family. It has a shared living room, a small kitchen and a quiet corner where I can study. Shops and a bus stop are nearby, so daily errands are straightforward."],
  [/home|accommodation/i, /who do you live with/i, "I live with my family. We are all fairly busy during the day, but we usually see each other at dinner or in the living room afterwards. I like having company at home while still having my own study space."],
  [/websites/i, /what kinds of websites do you often visit/i, "I mostly visit my university's learning platform, online dictionaries and a few news sites. I use them to check course information or look up a word, rather than browsing without a purpose. For entertainment, I occasionally watch short science videos."],
  [/websites/i, /what is your favourite website/i, "My favourite website is probably Bilibili, because I can find lectures, documentaries and lighter videos in one place. I mainly use it to watch explanations of topics I am curious about, and I like being able to save useful videos."],
  [/websites/i, /are there any changes to the websites you often visit/i, "The sites I use have become much better on mobile, and search results are usually more personalised. That saves time, but it can also keep showing me similar material. I still prefer a clear search bar and reliable sources to too many recommendations."],
  [/websites/i, /what kinds of websites are popular in your country/i, "Short-video and shopping platforms are very popular in China, along with messaging and news apps. People use them for entertainment, daily purchases and quick updates. I think convenience is the main reason, although it is easy to spend longer on them than intended."],
  [/websites/i, /do you prefer getting information from websites or books/i, "For a quick fact, I prefer a website because I can search it in seconds. If I am studying a complex topic, I would rather use a book or a reliable textbook, since the information is usually organised in a more focused way."],
  [/websites/i, /would you like to have your own website/i, "Maybe. I would make a simple portfolio with a few projects and notes about mathematics or data analysis. It could be useful when I apply for work after graduation, but I would keep it clear and update it only when I had something worthwhile to add."],
  [/websites/i, /what have you learned from websites that help with your life or studies/i, "Online tutorials have taught me basic spreadsheet skills and how to use tools for data analysis. I usually follow a short example, then try it with a small dataset from my coursework. That practical approach makes the information easier to remember."],
  [/computers\/tablets/i, /would you like to use a computer or tablet/i, "Yes, I use a computer almost every day for coursework. A laptop is much more comfortable than a phone for writing proofs, checking data and joining online meetings. I would also use a tablet for reading, but it would not replace my laptop."],
  [/computers\/tablets/i, /in what conditions would you use a computer or tablet/i, "I use a laptop when I need to write an assignment, analyse data or follow a lecture online. For checking a message or reading a short article, my phone is enough. The task and how long I need to focus determine the device."],
  [/computers\/tablets/i, /when was the first time you used a computer or tablet/i, "I first used a family computer in primary school, mainly to play simple games and type short homework assignments. I remember needing both hands to find the right keys. Later, school projects taught me how useful it could be for research."],
  [/computers\/tablets/i, /what would your life be like without computers or tablets/i, "Without computers, my coursework would take longer because lecture notes, research papers and data tools are mostly online. I could still read books and write by hand, but collaborating with classmates would be less convenient. I would manage, though."],
  [/computers\/tablets/i, /in what conditions would it be difficult for you to use a computer or tablet/i, "It would be difficult if the battery were dead and I had no charger, or if the internet failed during an online task. On the move, a phone is easier to carry. For detailed work, though, I need a proper keyboard."],
  [/scenery/i, /do you look out the window at the scenery when travelling by bus or car/i, "Yes, especially on a longer journey when I am not in a hurry. I like watching the view change from busy streets to open fields or hills. On a familiar commute, though, I usually read or listen to a podcast."],
  [/scenery/i, /do you prefer the mountains or the sea/i, "I would choose the sea for a relaxing break. I enjoy the open horizon and the sound of the waves, and there is usually a path where I can walk. Mountains are beautiful too, but they take more effort to explore."],
  [/scenery|views/i, /do you like to take scenery pictures|do you like taking pictures of different views/i, "Yes, if the light or the view is unusually good. I take a quick picture to remember the place, but I try not to spend the whole visit looking at my phone. A photograph rarely captures the atmosphere completely."],
  [/scenery/i, /what are the most beautiful sights you have seen while traveling/i, "One view I remember was West Lake in Hangzhou just after rain. The hills looked faint through the mist, and the water was almost still. I took a photo, but the quiet atmosphere was more memorable than the picture."],
  [/views/i, /do you prefer views in urban areas or rural areas/i, "I usually prefer rural views because they feel more open and there is less traffic noise. Still, I enjoy a city skyline at night, especially when the streets are lively. It depends on whether I want energy or a quieter change of pace."],
  [/views/i, /do you prefer views in your own country or in other countries/i, "I enjoy both, but familiar views in China often feel more meaningful because I understand the local context. Views abroad can be surprising and broaden my perspective. I would not rank one above the other; the place and the experience matter more."],
  [/views/i, /have you seen an unforgettable and beautiful view or scenery/i, "I remember seeing the mountains around West Lake in Hangzhou after a light rain. The mist softened the outline of the hills, and the lake was calm despite being close to the city. It was a simple view, but the timing made it special."],
  [/clothing/i, /what kind of clothes do you like to wear/i, "I like comfortable clothes in simple colours, especially jeans or trousers with a plain T-shirt. They are easy to match and work for most university days. I keep a smarter jacket for presentations or family occasions."],
  [/clothing/i, /do you prefer to wear comfortable and casual clothes or smart clothes/i, "I prefer comfortable, casual clothes for most days because I walk between classes and spend a lot of time sitting in lectures. I wear something smarter for a presentation or formal event, but comfort comes first."],
  [/clothing/i, /do you like wearing t-shirts/i, "Yes, I wear T-shirts quite often, especially in warm weather or when I am studying at home. They are comfortable and easy to wash. I usually choose a plain one because it goes with most of my trousers."],
  [/clothing/i, /do you spend a lot of time choosing clothes/i, "No, not really. I usually decide in a few minutes because most of my clothes are easy to match. I might spend longer choosing something for a presentation, but I do not plan a different outfit for every day."],
  [/clothing/i, /do you wear different styles of clothes on weekdays and weekends/i, "A little. On weekdays I usually wear comfortable clothes for lectures, while at weekends I might choose something more relaxed or meet friends in a slightly smarter outfit. I do not change my style dramatically, though."],
  [/clothing/i, /what colour clothes do you like/i, "I tend to wear navy, grey and white because those colours are easy to combine. I sometimes choose a brighter colour for a jacket or shirt, but I would not want my whole wardrobe to be difficult to match."],
  [/building/i, /are there tall buildings near your home/i, "Yes, there are several apartment blocks near my home, although none is especially unusual. They have shops on the ground floor, which is convenient, but I prefer the quieter streets with trees a little farther away."],
  [/building/i, /do you take photos of buildings/i, "Sometimes, especially if an older building has an interesting entrance or roof. I am more likely to take a photo while travelling than near home, because familiar buildings stop catching my attention after a while."],
  [/building/i, /is there a building that you would like to visit/i, "I would like to visit the National Centre for the Performing Arts in Beijing. Its shape is very distinctive, and I would be interested to see how the interior works as a concert venue rather than just looking at it from outside."],
  [/building/i, /do you want to live in a tall building/i, "I would not mind living in a tall building if the lifts were reliable and there was enough natural light. The view could be nice, but I would care more about sound insulation, safety and nearby transport."],
  [/public gardens and parks/i, /did you like going to parks as a child/i, "Yes, I liked the playgrounds and open space. I used to run around or play simple games with other children, and we could stay there until our parents called us home."],
  [/public gardens and parks/i, /do you still like going to parks now/i, "Yes, although I use them differently now. I usually go for a walk or sit somewhere quiet after studying, rather than spend the whole time playing. It is an easy way to get outside without planning a trip."],
  [/public gardens and parks/i, /would you like to see more parks in your city/i, "Yes, especially small parks in residential areas. They would give people somewhere to walk or sit without travelling across the city. Even a few trees and benches can make a busy neighbourhood feel more pleasant."],
  [/public gardens and parks/i, /are there any parks you want to go to in the future/i, "I would like to visit a larger botanical garden outside the city. It would be interesting to see plants from different regions and spend a quiet afternoon there, perhaps taking a slow walk with a friend."],
  [/public gardens and parks/i, /would you prefer to play in a personal garden or public garden/i, "I would choose a public garden because it usually has more space and people can meet there. A private garden would be quieter, but I do not have one at home, and I like seeing families use a shared green space."],
  [/public gardens and parks/i, /how are the parks today different from those you visited as a kid/i, "Parks today often have better paths, exercise equipment and areas for different age groups. The ones I visited as a child were simpler, with a playground and open ground. I still think children need room for unstructured play."],
  [/public gardens and parks/i, /what do you like to do when visiting a park/i, "I usually walk slowly, find a bench and take a short break from screens. If I go with a friend, we might talk while walking rather than sit in one place. I do not need a special activity."],
  [/public gardens and parks/i, /would you like to play in a public garden or park/i, "Yes, if there were a suitable space for it. I would be happy to play badminton or throw a frisbee with friends, as long as we were not disturbing people who came there to relax."],
  [/hometown/i, /did you learn about the history of your hometown at school/i, "We learned a little about local history at school, mainly through a few important events and well-known people. I remember the general outline, but I would like to learn more about how ordinary families lived in the past."],
  [/hometown/i, /have you learned anything about the history of your hometown/i, "Yes, I have learned more by visiting a local museum and reading short articles online. I am especially interested in how the city changed as transport and industry developed, because those changes still affect where people live today."],
  [/hometown/i, /did you learn about the culture of your hometown in your childhood/i, "Mostly through family routines and school activities rather than formal lessons. We celebrated local festivals, ate familiar dishes and heard stories from older relatives. I understood more about their meaning as I got older and began asking questions."],
  [/hometown/i, /please describe your hometown a little/i, "It is a medium-sized city with busy commercial streets and quieter residential areas. Public transport makes it fairly easy to get around, and there are parks where people can take a break. It feels lively without being overwhelming."],
  [/the area you live in/i, /do you know any famous people in your area/i, "I do not know anyone personally who is famous. There are a few people from the wider city who appear in local news, but day to day I am more likely to recognise shop owners or neighbours than public figures."],
  [/the area you live in/i, /do you live in a noisy or a quiet area/i, "My street is fairly quiet, especially at night, although the main road nearby gets busy during rush hour. I like that balance because shops and buses are close, but I can still study at home without much disturbance."],
  [/morning time/i, /do you like getting up early in the morning/i, "I like getting up early when I have slept enough. The morning is quiet, so I can review my plans or work through a problem before messages and classes start. I am less enthusiastic about it after a late night."],
  [/morning time/i, /are there any differences between what you do in the morning now and what you did in the past/i, "When I was younger, my parents organised most of my morning routine before school. Now I check my own timetable, prepare what I need for class and decide whether to study or have breakfast first."],
  [/morning time/i, /do you spend your mornings doing the same things on both weekends and weekdays/i, "Not exactly. On weekdays I get ready quickly and leave for class, while at weekends I usually wake up later and have a slower breakfast. I keep the basic routine, but there is less pressure to watch the clock."],
  [/opportunities/i, /do you often get new opportunities/i, "From time to time, especially through university projects or people I meet in my department. I do not get a major opportunity every week, but small chances to present work or learn a new tool come up quite regularly."],
  [/opportunities/i, /do you like taking on new opportunities/i, "Usually, yes, as long as I can manage the commitment alongside my studies. A new project can show me what I need to improve, even if it feels unfamiliar at first. I try to understand the time involved before agreeing."],
  [/opportunities/i, /should people try as many different things as they can/i, "Trying different things can help people discover what they enjoy, but they do not need to say yes to everything. Time and energy are limited, so I think it is better to explore a few options thoughtfully and keep the ones that feel worthwhile."],
  [/music/i, /does happy music make you feel more excited/i, "Usually, yes. Upbeat music gives me a quick lift, especially when I am walking to class or doing a routine task. If I need to concentrate on a difficult proof, though, I prefer silence. That is my preference."],
  [/music/i, /do you listen to music while doing other things/i, "Sometimes, when I am walking or doing simple chores. I turn it off when I need to read carefully or work through a mathematics problem, because lyrics can distract me from the details. Instrumental music is easier."],
  [/lost and found/i, /will you post on social media if you lose your item/i, "I might post a short notice in a local or campus group, but I would leave out private details. If it were a bank card or student ID, I would contact the relevant office first."],
  [/lost and found/i, /what will you do if you find something lost by others/i, "I would hand it to staff at the place where I found it, such as a shop counter or campus reception. If there were no staff nearby, I would contact the owner only through a safe, public channel."],
  [/street market/i, /what do people usually buy on the street market/i, "People often buy fresh fruit, vegetables, snacks and inexpensive household items at street markets. I like the food stalls because the produce is seasonal, and buyers can ask vendors where it came from before choosing what to buy."],
  [/life stages/i, /at what age do you think people are the happiest/i, "I do not think happiness belongs to one age. People may enjoy childhood's freedom or adulthood's independence, depending on their health, relationships and responsibilities. That is different for everyone."],
  [/reading/i, /do you prefer to read on paper or on a screen/i, "I prefer paper for a book I want to read carefully, because it is easier for me to stay focused. For articles and reference material, a screen is quicker to search and carry, particularly when I travel."],
  [/reading/i, /do you prefer scanning or detailed reading/i, "It depends on what I need. I scan a page first to find a relevant point, then read that section carefully if I need to understand an argument or check a detail. I use both methods."],
  [/sports team/i, /is team sports popular in your culture/i, "Yes, team sports are popular, particularly football and basketball. People follow professional matches, but schools and universities also organise games, so it is common to play casually with classmates. There are many local courts, so it is a popular hobby."],
  [/name/i, /do you often forget people.s names/i, "Occasionally, especially when I meet several people at once. I usually remember a name better if I repeat it during the conversation or connect it with something we discussed."],
  [/name/i, /how do you remember people.s names/i, "I repeat the person's name once after we are introduced and try to connect it with a detail from our conversation. That works better for me than memorising a list."],
  [/name/i, /is it easy for you to remember people.s names/i, "Not always, particularly at a large event where I meet many people quickly. I am better at remembering names after I have spoken to someone a few times."],
  [/singing/i, /do you like singing/i, "Yes, casually. I sing along to familiar songs at home or during karaoke with friends, although I am not confident enough to perform on a stage."],
  [/singing/i, /^.*\bwhy\b/i, "Mostly because it is an easy way to relax. I often sing along to a song I know well, and I do not worry about getting every note right."],
  [/singing/i, /do you like listening to others singing/i, "Yes, if the person is enjoying it. I like hearing friends sing at karaoke because the atmosphere is relaxed, even when nobody has a trained voice."],
  [/life stages/i, /what did you often do with your friends in your childhood/i, "We usually rode our bicycles or played simple games near home after school. We did not need much equipment, and we often stayed outside until it was time for dinner."],
  [/life stages/i, /at what age do you think people are the happiest/i, "I do not think happiness belongs to one age. People may enjoy childhood's freedom or adulthood's independence, depending on their health, relationships and responsibilities."],
  [/pets and animals/i, /how often do you visit a zoo/i, "Not very often, perhaps once every few years. I went more regularly on school trips as a child, but now I would choose a zoo only if it had good animal-care standards."],
  [/pets and animals/i, /are there many people keeping pets in your country/i, "Yes, especially in cities, where cats and small dogs are common in apartments. People enjoy the company, though owners need to plan for exercise, vet bills and enough space."],
  [/dream and ambition/i, /what was your childhood dream/i, "When I was a child, I thought being a scientist would be exciting because I liked asking how things worked. My plans have become more practical, but I still enjoy solving unfamiliar problems."],
  [/dream and ambition/i, /are you the kind of person who sticks to dreams/i, "I try to stay committed, but I am willing to adjust the route if I learn something new. For example, I am exploring analytical careers while finishing my mathematics degree."],
  [/dream and ambition/i, /what is your dream job/i, "I would like to work as a data analyst, using mathematics to answer practical questions. It would let me keep learning while seeing how careful analysis can help people make decisions."],
  [/films\/cinemas/i, /what films do you like/i, "I like character-driven mysteries because I enjoy following the clues and working out what a character has missed. I prefer a believable story to impressive effects without much plot."],
  [/films\/cinemas/i, /do you often go to the cinema with your friends/i, "Not very often, perhaps every couple of months. We usually go when there is a film everyone wants to see, then get something to eat and discuss it afterwards."],
  [/films\/cinemas/i, /is going to the cinema a good way to spend time with friends/i, "Yes, especially when we choose the film together. We share the experience without needing to talk throughout it, and then have something specific to discuss afterwards."],
  [/films\/cinemas/i, /do you prefer to watch films at home or in the cinema/i, "Usually at home, because it is more convenient and I can pause the film. I choose the cinema for a release I am excited about or a film with striking visuals."],
  [/cars?/i, /car colou?rs? (?:are|is) important/i, "Not particularly. I would care more about reliability and running costs than paintwork; if I had to choose, I would go for dark grey because it stays looking neat between washes. For daily use, that practical side matters more to me than making a statement."],
  [/cars?/i, /enjoy traveling by car.*when you were a kid|enjoy travelling by car.*when you were a kid/i, "Yes, especially on family trips. I used to watch the scenery and then fall asleep once the road became steady. Those journeys felt like a small break from routine, even if we were only going to visit relatives for the day."],
  [/cars?/i, /what types of cars do you like/i, "I would choose a small electric car. It should be cheaper to run and easier to park near campus or work, which matters more to me than having a powerful engine or a flashy design."],
  [/cars?/i, /prefer to be a driver or a passenger|prefer to drive a car/i, "I would rather be a passenger on a long or busy journey because I can relax and look out of the window. On a quiet short trip, though, driving would give me more control over the route."],
  [/cars?/i, /what do you usually do when there is a traffic jam/i, "I check the delay, put on a podcast and try not to keep watching the clock. If someone is waiting for me, I send a quick message, then accept that the traffic is outside my control."],
  [/cars?/i, /buy an expensive car in the future/i, "Probably not. I would rather spend that money on travel or keep it for something more useful. An expensive car would bring higher costs, and I do not care enough about the badge to justify them."],
  [/cars?/i, /too many cars in the area/i, "Yes, especially near the main roads at rush hour. The traffic is slowest when people leave work at the same time, so better public transport would help more than simply widening every road."],
  [/cars?/i, /long car journeys|long journeys.*when you were a child/i, "Yes, I remember one drive to visit relatives that took most of the day. I watched the scenery for a while, then slept until we stopped for food, so the journey felt longer than the visit."],
  [/hometown|city you live|area you live/i, /what is your hometown famous for|what is your hometown known for/i, "My hometown is best known for its local food and a historic district. People from nearby places often visit at weekends, although daily life there feels much quieter than the tourist streets suggest."],
  [/advertisement/i, /often see advertisements when you are on your phone or computer/i, "Yes, quite often, especially in short videos and free apps. I usually skip them, but a clear demonstration can catch my attention if I am already looking for that kind of product."],
  [/advertisement/i, /what kind of advertising do you like/i, "I prefer short adverts that show how something works instead of making big promises. A useful example or a clear price is more convincing to me than a celebrity or a dramatic slogan."],
  [/advertisement/i, /do you like advertisements/i, "It depends on the advert. I do not mind one that is brief and informative, but repeated pop-ups interrupt what I am doing and make me less likely to trust the product."],
  [/advertisement/i, /made an impression.*when you were a child/i, "I remember a snack advert with a catchy tune from primary school. My classmates and I used to sing it during breaks, although none of us could remember the product details afterwards."],
  [/advertisement/i, /bought something because of an advertisement/i, "Yes, I once tried a snack after seeing it in an online advert. It was fine, but not as special as the video made it look, so now I check reviews before buying."],
  [/work or studies/i, /what subjects are you studying|what are you studying/i, "I am a final-year mathematics student. My courses include statistics and more theoretical subjects, and I like seeing how the same careful reasoning can be used in very different problems."],
  [/work or studies/i, /why did you choose to study that subject/i, "I chose mathematics because I enjoy finding the logic behind a problem rather than memorising a fixed procedure. Statistics later showed me that those ideas can also help answer practical questions."],
  [/work or studies/i, /do you like your subject/i, "Yes, especially when a difficult idea finally makes sense. A proof can take time to write clearly, but I enjoy the moment when each step follows from the one before it."],
  [/work or studies/i, /plans for your studies in the next five years/i, "I hope to finish my degree, gain practical experience and decide whether further study suits me. I am also building my data and communication skills because both matter in analytical work."],
  [/work or studies/i, /what technology do you use when you study/i, "I mainly use a laptop for lecture notes and assignments, plus spreadsheets or simple programs for data. I still check important calculations by hand because software can make a wrong step look convincing."],
  [/fruit|vegetable/i, /do people in your country like planting vegetables/i, "Yes, quite a few people do, especially those with a balcony or a small garden. My grandparents grew seasonal vegetables when I was younger, and I can see why people enjoy having something fresh to pick."],
  [/fruit|vegetable/i, /disliked as a child/i, "I was not keen on bitter melon as a child because the taste seemed too strong. I am more open to it now, especially when it is cooked with eggs, but it still would not be my first choice."],
  [/fruit|vegetable/i, /what kind of fruits and vegetables do you dislike/i, "I am not a big fan of bitter melon or fruit that is overly sour. I do eat them occasionally if they are part of a meal, but I usually choose sweeter fruit and milder vegetables."],
  [/fruit|vegetable/i, /where do you usually buy fruit/i, "I usually buy fruit and vegetables at a nearby supermarket because I can get everything in one stop. If I have more time, I like the local market, where seasonal produce often looks fresher."],
  [/fruit|vegetable/i, /how often do you eat fruit/i, "I have fruit most days, usually with breakfast or as a snack between classes. Keeping apples or bananas at home makes it easy to choose something fresh, even when I have a busy study schedule."],
  [/headphones/i, /in what conditions would you not use headphones/i, "I take them off when I am crossing a busy road or need to listen for an announcement. I also avoid wearing them in a conversation, since it can make the other person feel that I am not paying attention."],
  [/headphones/i, /when would you use headphones/i, "I use headphones on the bus or when I am listening to a lecture recording at home. I would not wear them while walking near traffic, because hearing what is around me matters more. I want to stay alert."],
  [/mirrors/i, /how often/i, "I probably look in a mirror a few times a day when I get ready or check my appearance before leaving home. I do not spend long in front of it; I just want to make sure I look presentable."],
  [/science/i, /do chinese people often visit science museums/i, "Some families do, especially when a museum has hands-on exhibits for children. I went to one on a school trip, and the interactive displays made the visit more engaging than simply reading information boards."],
  [/shoes/i, /how much money do you usually spend/i, "I usually spend a moderate amount on shoes, perhaps a few hundred yuan if I expect to wear them often. I would rather pay for a comfortable pair that lasts than replace a cheap one after a few months."],
  [/shoes/i, /how often/i, "I buy shoes only when my current pair is worn out or I need something for a different purpose. I walk a lot between classes, so comfort matters more to me than having several fashionable pairs."],
  [/shopping/i, /how often do you go shopping/i, "I buy groceries once or twice a week, but I do not go to shops just to browse very often. For clothes or electronics, I compare a few options first and buy only when I actually need something."],
  [/singing/i, /do you think singing can bring happiness/i, "Yes, especially when people sing together without worrying about being perfect. Even singing along to a familiar song with friends can lift the mood, because everyone is taking part rather than just listening."],
  [/social media/i, /what do people often do on social media/i, "People use it to share photos, follow news and keep up with friends. I mostly check messages and updates from classmates, although short videos can easily take more time than I intended."],
  [/teachers/i, /in what way has your favourite teacher helped you/i, "My favourite teacher helped me explain my ideas instead of worrying about making every sentence perfect. When I got stuck, she would ask a smaller question that helped me work out the next step for myself."],
  [/work or studies/i, /what are the benefits of being your age/i, "At this age, I have some independence but still have room to change direction. I am finishing my mathematics degree, so I can try internships and learn what kind of work suits me before making a long-term commitment."],
  [/work or studies/i, /do you want to change your major/i, "No, I do not plan to change my major. Mathematics can be demanding, but I enjoy the reasoning behind it, and statistics has shown me how it can be applied to practical questions."],
  [/work or studies/i, /how much time do you spend on your studies each week/i, "It varies with deadlines, but I probably spend around thirty hours a week in classes and independent study. I try to work through problem sets regularly, since leaving several weeks of mathematics to the last minute rarely works."],
  [/work or studies/i, /what do you think is the most important at the moment/i, "At the moment, finishing my degree well is the main priority. I am also building practical skills and preparing for work after graduation, but I need to balance that with my final-year coursework."],
  [/work or studies/i, /who helps you the most/i, "My classmates help me most with difficult coursework. We sometimes compare approaches to a proof or check a calculation together, and explaining my reasoning to someone else often shows me where I have missed a step."],
  [/hometown/i, /where is your hometown/i, "I grew up in a city in China, and I am now studying away from home. It is familiar to me because my family and many of my childhood memories are still there, even though I see it differently when I visit as an adult."],
  [/hometown/i, /is that a big city or a small place/i, "I would call it a medium-sized city. It has the usual shopping areas and public transport, but it is not so large that getting across town takes the whole day. That balance makes it fairly convenient to live in."],
  [/hometown/i, /how long have you been living there/i, "I lived there for most of my childhood, then moved away to attend university. I still go back during longer holidays, so it remains the place I associate with home, even though my daily routine is now somewhere else."],
  [/hometown/i, /continue living there for a long time/i, "I am not sure I will settle there permanently. I would like to get some work experience after graduation, and that may take me to another city, but I can imagine moving back later if the right opportunity comes up."],
  [/hometown/i, /do you like your hometown|do you like living there/i, "Yes, I do. It feels familiar, and daily things such as getting food or meeting relatives are easy to arrange. It can be busy at peak times, but I enjoy returning to a place where I know the streets well."],
  [/hometown/i, /anything you dislike about it/i, "The main drawback is traffic, particularly when people are travelling home from work. A few roads get crowded, so a short journey can take longer than expected. Apart from that, I find it a comfortable place to visit and spend time with family."],
  [/hometown/i, /are there many young people in your hometown/i, "Yes, there are quite a lot, partly because local universities and colleges attract students from nearby areas. You see groups meeting for food or studying in cafes, although some graduates move away to find work after finishing their courses."],
  [/hometown/i, /good place for young people to pursue their careers/i, "It is a reasonable place to start a career, especially in education, retail and local services. For more specialised jobs, graduates may have fewer choices than in a major city, so some leave for a wider job market."],
  [/hometown/i, /learn.*history|history.*school|culture.*childhood/i, "At school, we learned a little about the area's history and local traditions, though it was not a major subject. I remember the stories more clearly when a teacher connected them to an old street or building we could actually visit."],
  [/the city you live in/i, /what city do you live in/i, "I live in a university city at the moment. It has a large student population, plenty of places to eat and reliable public transport, so most things I need are within an easy trip from campus."],
  [/the city you live in/i, /are there big changes in this city/i, "Yes. There have been new residential buildings and more shops near the main roads, and a few bus routes have changed as the area has grown. The city feels more convenient, although rush-hour traffic has also become heavier."],
  [/the city you live in/i, /is this city your permanent residence/i, "Probably not. I am here for university, so after graduation I may move for work or further study. I have enjoyed living here, though, and I would consider coming back if a good opportunity suited me."],
  [/the city you live in/i, /are there people of different ages living in this city/i, "Yes, although some neighbourhoods have more students than others. Near campus I see mostly young adults, while residential areas have families and older people. That mix gives the city quite different rhythms from one district to another."],
  [/the city you live in/i, /are the people friendly|friendly to children and old people/i, "Generally, yes. People are used to students and families sharing public spaces, and most are willing to help if someone asks. It could still be easier to get around for older people if crossings and pavements were better maintained."],
  [/the area you live in/i, /do you know any of your neighbors|people in your neighborhood/i, "I know a few neighbours well enough to greet them and exchange small favours, but we are not close friends. People have different schedules, so we mostly chat briefly in the lift or around the entrance."],
  [/opportunities/i, /opportunities to take part in new activities as a child/i, "Yes. At primary school I tried a few activities, including drawing and a short sports club. I was not especially good at either, but it was fun to try them with classmates before homework and exams became a bigger part of life."],
  [/shopping/i, /do you like shopping/i, "I do when I have something specific in mind. I like comparing a few options and checking whether an item will last, but I do not enjoy walking around a crowded mall for hours without a reason to be there."],
  [/social media/i, /have you ever posted anything on social media/i, "Yes, mostly photos from trips or small updates for friends. I do not post every day because I prefer to keep some parts of my life private, but it is convenient for sharing a moment with people I do not see often."],
  [/social media/i, /when did you start using social media/i, "I started using it in secondary school, mainly to keep in touch with classmates after lessons. At first I mostly checked messages and photos; now I use it more selectively because I do not want it to interrupt my study time."],
  [/work or studies/i, /do you think that your subject is popular/i, "Mathematics has a mixed image. Some students enjoy the logic and problem-solving, while others find the abstract parts intimidating. I think statistics is becoming more popular because people see how it is used in business, science and public policy."],
  [/work or studies/i, /prefer to study in the mornings or in the afternoons/i, "I prefer studying in the morning, when I am usually more alert. I try to use that time for problem sets or proofs that need concentration, then leave reading and routine tasks for later in the day."],
  [/work or studies/i, /are you looking forward to working/i, "Yes, although I know the first job will involve a lot of learning. I am looking forward to using mathematics on practical problems and working with a team, rather than only submitting assignments for a grade."],
  [/work or studies/i, /what changes would you like to see in your school/i, "I would like to see more chances for students to work on practical projects with real data. The theory is important, but applying it in a team would help us practise explaining results and understand what a job might involve."],
  [/work or studies/i, /what work do you do/i, "I am a full-time mathematics student at the moment, so my main work is coursework. I spend a lot of time on problem sets and a final-year project, and I am starting to look at analytical roles for after graduation."],
  [/work or studies/i, /why did you choose to do that type of work/i, "I have not started a full-time job yet. I am interested in analytical work because I like finding patterns in information and checking whether the evidence supports a conclusion, which connects naturally with what I study."],
  [/work or studies/i, /do you like your job/i, "I am still a student rather than a full-time employee. I do enjoy the independent side of my studies, especially solving a difficult problem, though I am also looking forward to seeing how those skills are used in a workplace."],
  [/work or studies/i, /requirements did you need to meet to get your current job/i, "I do not have a full-time job yet; I am finishing my mathematics degree. For the analytical roles I am considering, employers usually look for careful work with data, clear communication and some programming experience, so I am building those skills now."],
  [/work or studies/i, /plans for your work in the next five years/i, "I hope to start in an analytical role and learn how a team uses data to make decisions. After gaining experience, I will decide whether I want to specialise further or return to university for postgraduate study."],
  [/work or studies/i, /do you want to change to another job/i, "I have not started my first full-time job yet, so it is too early to talk about changing it. I would like to try an analytical role first and see which parts of the work suit me before making a longer-term decision."],
  [/work or studies/i, /do you miss being a student/i, "I am still studying, but I can see that I will miss parts of it, especially discussing problems with classmates. I will not miss deadlines piling up near exams, so I hope work gives me a steadier routine."],
  [/street market/i, /are there many street markets in china/i, "Yes, especially in older neighbourhoods and near busy residential areas. They sell vegetables, snacks and inexpensive household items, and I like that shoppers can talk directly with the stall owners instead of choosing everything from a shelf."],
  [/reading/i, /do you like reading/i, "Yes, when I can give it my attention. I read course materials most days, but in my free time I prefer fiction or a long article that lets me follow an idea properly instead of switching between short posts."],
  [/hometown/i, /what do you like \(most\) about your hometown/i, "I like that it feels familiar without being boring. I know where to find good food and quiet places to walk, and visiting family is easy. When I go back after a busy semester, the slower pace helps me relax."],
  [/the area you live in/i, /do you like the area that you live in/i, "Yes, mostly because daily things are close by. I can get food, take public transport and meet a classmate without planning much, but there are also a couple of quieter streets where I can walk after studying."],
  [/the city you live in/i, /do you like this city/i, "Yes, I do. It is lively enough to have good transport and plenty of places to eat, but I can still find quieter areas near campus. That mix makes it convenient for student life without feeling overwhelming."],
  [/the city you live in/i, /do you like this city.*why/i, "Mainly because it is practical for student life. I can get to campus by public transport, find affordable food nearby and meet friends without travelling far, so the city makes a busy week easier to manage."],
  [/^watch$/i, /why do some people wear expensive watches/i, "Some people appreciate the craftsmanship, while others treat a watch as a status symbol. I would not spend that much myself, because my phone already tells the time and I would rather put the money towards something I use every day."],
  [/^watch$/i, /important to wear a watch/i, "It is convenient, but I do not think it is essential now that most people carry a phone. I wear one on a busy day because I can check the time quickly without opening another app or getting distracted by notifications."],
  [/mirrors/i, /have you ever bought mirrors/i, "Yes, I bought a small mirror for my desk when I moved into student accommodation. It is useful when I am getting ready, but I chose a simple one because I did not want it to take up much space."],
  [/jokes & comedies/i, /have you ever watched a live show/i, "Yes, I went to a small stand-up show with friends at university. The room was intimate, so the comedian could react to the audience, and even an ordinary joke felt funnier when everyone laughed together."],
  [/outer space|stars/i, /do you like science fiction movies/i, "Yes, especially films that use space as a setting for questions about people and society. I enjoy the ideas more than complicated special effects, and a good science-fiction story can make me curious about real astronomy too."],
  [/outer space|stars/i, /do you want to know more about outer space/i, "Yes, I would. I am curious about how planets form and whether life could exist elsewhere, although I usually learn through short articles or documentaries rather than technical books. A clear explanation makes me want to learn more."],
  [/outer space|stars/i, /do you want to go into outer space/i, "Probably not. Seeing Earth from space would be incredible, but the cost, risk and training would put me off. I would be perfectly happy visiting an observatory or seeing a clear night sky from the ground."],
  [/paper/i, /do people still keep handwritten letters/i, "Some people keep them, especially letters from relatives or friends who live far away. They feel personal because someone took time to write them, although most everyday conversations happen through messaging apps now."],
  [/paper/i, /do you still write physical letters/i, "Not very often. I usually send a message because it is quicker, but I might write a card for a birthday or a graduation when I want the words to feel more personal."],
  [/^watch$/i, /why\b/i, "A watch is useful when I want to check the time quickly, but I do not think everyone needs one. Since phones are always nearby, it comes down to personal preference and whether wearing a watch feels comfortable."],
  [/lost and found/i, /have you ever lost your keys/i, "Yes, I once left my keys in a classroom after a late lecture. I went back as soon as I noticed, and someone had handed them to the reception desk, so now I check my pockets before leaving."],
  [/lost and found/i, /report to the police.*finding something lost|do you report to the police when finding/i, "Not usually. I would first hand the item to staff at the place where I found it, such as a station desk or shop counter. I would contact the police if it seemed valuable or there were no suitable staff nearby."],
  [/pets and animals/i, /have you ever visited a zoo/i, "Yes, I went to a zoo on a primary-school trip. I remember watching the elephants for a long time, although now I am more aware that animals need enough space and good care, not just an enclosure for visitors."],
  [/pets and animals/i, /how often do you visit a zoo/i, "I rarely go to a zoo now, perhaps once every few years. I enjoy seeing animals, but I would rather visit a well-run conservation centre than a place where the enclosures seem too small."],
  [/pets and animals/i, /where do you prefer to keep your pet/i, "I would keep a small pet indoors, where it would be safer and easier to look after. A dog would still need regular walks outside, so I would think carefully about the animal's needs before choosing one."],
  [/pets and animals/i, /should schools teach students knowledge about pets/i, "Yes, basic lessons would help children understand that pets need food, exercise and regular care. It could also teach them to approach unfamiliar animals safely instead of assuming that every dog or cat wants to be touched."],
  [/sports team/i, /do you like watching team games/i, "Yes, especially a close game where the score can change quickly. I enjoy seeing how players coordinate and adjust their tactics, and watching with friends makes it more fun to react to the key moments together."],
  [/sports programs/i, /who do you like to watch sports games with/i, "I usually watch with friends or classmates who follow the same sport. We can talk about the players and react to the match, which makes a long game more engaging than watching by myself. It feels more social."],
  [/sports programs/i, /prefer to watch sports games alone or with a group/i, "I prefer watching with a small group of friends. We can react to the same moments and discuss the tactics, but a very large group can be distracting if I am trying to follow a close match."],
  [/friends/i, /where do you often meet each other/i, "We often meet near campus, usually at a casual restaurant or a cafe where it is easy to talk. If the weather is good, we might walk around a nearby park instead of sitting indoors."],
  [/hobby/i, /did you have any hobbies when you were a child/i, "I liked drawing and riding my bicycle when I was a child. Neither was a serious hobby, but I enjoyed having something to do after school that did not feel like another lesson."],
  [/hobby/i, /do you have a hobby that you.ve had since childhood/i, "I have kept a small interest in drawing since childhood, although I do it less often now. It is a relaxing change from mathematics, because I can focus on shapes and colours rather than whether each step is correct."],
  [/singing/i, /have you ever learnt how to sing|have you ever taken a singing class/i, "I have never taken a proper singing class. I sometimes sing along to songs at home, but I would not call myself a confident singer; I mostly do it for fun when I am not worried about being heard."],
  [/scenery|views/i, /prefer the mountains or the sea/i, "I would choose the sea. I like the open horizon and the sound of the waves, and it feels relaxing to walk along the coast without needing to follow a particular route."],
  [/life stages/i, /plans for the next five years/i, "I hope to finish my mathematics degree, start work in an analytical field and become more confident working with real data. I would also like to keep enough time for friends and family instead of making every year about work."],
  [/life stages/i, /do you enjoy being the age you are now/i, "Yes. I have more independence than I did as a teenager, but I am still able to explore different career options. The uncertainty can be stressful, although it also means I have room to change direction."],
  [/outer space|stars/i, /do you want to know more about outer space/i, "Yes, definitely. I am curious about how planets form and whether life could exist elsewhere. I usually watch short documentaries or read accessible articles, and I would like to learn how astronomers study distant planets."],
  [/mirrors/i, /do you usually take a mirror with you/i, "Not usually. My phone camera is enough for a quick check on an ordinary day, and I might pack a small mirror if I am going to a formal event or will be out for a long time."],
  [/^paper$/i, /do you carry paper and pens with you/i, "Yes, I usually keep a small notebook and pen in my bag. They are handy for writing a quick reminder or sketching an idea, especially when taking out my laptop would be inconvenient."],
  [/^paper$/i, /do people still keep handwritten letters/i, "Some people keep them, especially letters from relatives or friends who live far away. A handwritten note feels personal because someone chose the words and took time to write it, even though most daily messages are digital now."],
  [/^paper$/i, /do you still write physical letters/i, "Not often. I usually send a message because it is quicker, but I write a card for a birthday or graduation when I want the note to feel more personal and worth keeping."],
  [/^paper$/i, /what did you like to do with paper as a child/i, "I used to fold paper planes and make simple cards for family occasions. I liked that I could turn an ordinary sheet into something different with just a pair of scissors and a little imagination."],
  [/^paper$/i, /have you made any crafts with paper/i, "Yes, mostly simple things such as greeting cards and paper decorations. I made them at school and sometimes at home with my family; they were not perfect, but making something by hand was enjoyable. I kept one card on my desk."],
  [/jokes & comedies/i, /are you good at telling jokes/i, "Not really. I can make friends laugh when I tell a story, but I am not quick with a punchline. I usually enjoy listening to other people more than trying to perform, especially in a large group."],
  [/jokes & comedies/i, /do your friends like to tell jokes/i, "A few of them do, especially when we are taking a break after class. Their jokes are usually about small things that happened that day, which feels more natural than memorising a punchline."],
  [/jokes & comedies/i, /are comedy shows popular in your country/i, "Yes, comedy shows are popular, particularly short online clips and stand-up performances. People share jokes that reflect everyday life, although humour can be very personal and a joke that works for one group may not work for another."],
  [/pets and animals/i, /what.s your favourite animal/i, "My favourite animal is probably a dog. I like how sociable and expressive they can be, and they often seem to notice when someone is upset. I do not have one now because looking after a pet takes real time."],
  [/pets and animals/i, /favourite animal.*why/i, "I like dogs because they are sociable and expressive, and they can become very close to the people who care for them. I would still want to be sure I had enough time for walks and daily care before getting one."],
  [/pets and animals/i, /what is the most popular animal in china/i, "Dogs and cats are probably the most common pets in China, especially in cities. Dogs are popular with families who have time to walk them, while cats suit people who want a more independent indoor companion."],
  [/pets and animals/i, /are there many people keeping pets in your country/i, "Yes, particularly in cities, where many families keep a cat or a small dog in their apartment. People enjoy the company, although responsible owners also need to think about space, exercise and vet bills."],
  [/life stages/i, /what do you think is the most important at the moment/i, "At the moment, finishing my degree and preparing for the next stage of life matter most. I am trying to make sensible career plans without letting that take over my health or the time I spend with people close to me."],
  [/life stages/i, /how do people remember each stage of their lives/i, "People often remember a stage through a few vivid details, such as a friendship, a place or a family routine. Photos can help, but a particular smell or song sometimes brings back a memory more strongly than looking at a date."],
  [/life stages/i, /at what age do you think people are the happiest/i, "I do not think there is one happiest age. Some people enjoy childhood because they have fewer responsibilities, while others feel happier as adults because they have more independence and control over their choices. That is different for everyone."],
  [/sports programs/i, /have you ever watched a sports game in a stadium/i, "Yes, I watched a university basketball match in a small stadium with classmates. It was much louder than watching on television, and being surrounded by other supporters made the close final minutes feel especially exciting."],
  [/politeness/i, /do you think being polite is very important/i, "Yes, I think it matters because a little courtesy makes shared situations easier. In a seminar, for example, letting someone finish before responding keeps a disagreement focused on the idea rather than the person."],
  [/secondary school/i, /is there anything you miss about your secondary school/i, "I miss seeing the same friends every day and having a familiar routine. We could talk between lessons without arranging it in advance, and those ordinary conversations are what I remember most clearly."],
  [/feeling bored/i, /do you think childhood is boring or adulthood is boring/i, "Neither stage is automatically boring, but adults often have less unplanned free time. Children can play without organising everything, while adults have more choice over their activities; for me, a mix of routine and free time is best."],
  [/gifts/i, /do you think you are good at choosing gifts/i, "I think I am fairly good at it when I know the person well. I pay attention to small hints about what they use or enjoy, so the present feels personal rather than expensive for its own sake."],
  [/history/i, /do you like history/i, "Yes, when it is connected to real people and places I can still visit. Personal stories make the past easier to follow, and comparing an old street with a modern one helps me picture how daily life changed."],
  [/old buildings/i, /why\b/i, "I would like to see a traditional courtyard house because its layout shows how families used to share space. It would be interesting to compare that design with the apartments people live in now. That contrast would make the visit memorable."],
];

function partOneAnswer(topic, question, index) {
  const p = partOneProfiles.find(([pattern]) => pattern.test(topic.title))?.[1] || p1Fallback;
  let q = question.toLowerCase().replace(/[?？]+$/, "").trim();
  if (/^(why|why or why not|how often|how long|where|when)$/.test(q) && index > 0) q = `${topic.questions[index - 1]} ${q}`.toLowerCase();
  const tailored = partOneSpecific.find(([topicPattern, questionPattern]) => topicPattern.test(topic.title) && questionPattern.test(q))?.[2];
  if (tailored) return expandPartOne(tailored, topic.title);
  let answer;
  const support = (first, second) => index % 2 === 0 ? first : second;
  if (/^why\b|why or why not/.test(q)) {
    answer = `${p.reason} ${support(p.example, p.past)}`;
  } else if (/how often|how long|what do you usually|what is your .*routine|what do you do/.test(q)) {
    answer = `${p.routine} ${support(p.example, p.reason)}`;
  } else if (/when you were|when did you|did you|have you ever|in your childhood|as a child|used to/.test(q)) {
    answer = `${p.past} ${support(p.example, p.reason)}`;
  } else if (/what type|what kind|which .* prefer|would you|will you|in the future|do you prefer/.test(q)) {
    answer = `${p.like} ${support(p.example, p.reason)}`;
  } else if (/where|who|when/.test(q)) {
    answer = `${p.routine} ${p.example}`;
  } else if (/do you like|do you enjoy|are you interested|is .* important|do you think|are there|is there/.test(q)) {
    answer = `${p.like} ${support(p.reason, p.example)}`;
  } else {
    answer = `${p.like} ${support(p.example, p.reason)}`;
  }
  return expandPartOne(answer, topic.title);
}

