function expandPartOne(answer, topicTitle) {
  if (countWords(answer) >= 35) return answer;
  const extra = partOneExtensions.find(([pattern]) => pattern.test(topicTitle))?.[1];
  if (extra && countWords(answer) + countWords(extra) <= 50) return `${answer} ${extra}`;
  return answer;
}

