function partTwoAnswer(topic) {
  const prompt = (topic.prompt || topic.title).toLowerCase().replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ");
  const story = partTwoOverrides.find(([pattern]) => pattern.test(prompt))?.[1]
    || partTwoStories.find(([pattern]) => pattern.test(prompt))?.[1]
    || p2FallbackStory;
  let extensionIndex = 7;
  if (/\b(?:app|program)\b/.test(prompt) && /describe a program|program or app|app on your/.test(prompt)) extensionIndex = 0;
  else if (/\b(?:film|movie|book|story|advertisement|video|documentary|interview(?:ed)?)\b|\btv show\b|\bonline program\b/.test(prompt)) extensionIndex = 3;
  else if (/\b(?:law|rule|policy)\b/.test(prompt)) extensionIndex = 5;
  else if (/^describe (?:a |an )?(?:person|friend|teacher|someone|relative|cousin)\b/.test(prompt)) extensionIndex = 2;
  else if (/\b(?:skill|learn|course|class|lesson|study|job|career|goal|ambition|work|project)\b/.test(prompt)) extensionIndex = 4;
  else if (/\b(?:food|cake|gift|item|object|technology|device|money|purchase|product)\b/.test(prompt)) extensionIndex = 6;
  else if (/\b(?:trip|journey|travel|commute|bicycle|motorcycle|car ride|transport|visit|city|place|building|river|lake|park|garden)\b/.test(prompt)) extensionIndex = 1;
  let extensionOverride;
  let shortExtensionOverride;
  if (/enjoyable evening/.test(prompt)) {
    extensionOverride = {
      past: "What I liked most was the feeling of being able to unwind with people who understood the work we had just finished. We did not need an elaborate plan or a special occasion; sharing a meal and walking home was enough. I went home in a better mood and felt more connected to my friends.",
    };
    shortExtensionOverride = "We still mention that bus story when we meet, so it has become a small shared memory for the group.";
  } else if (/history.*loves history|person who learns history/.test(prompt)) {
    extensionOverride = {
      past: "What I admire most is her curiosity. She does not treat history as a list of dates; she asks how a place changed over time and what evidence can tell us about it. Her approach has made me more curious about local stories, and I admire how patiently she keeps learning.",
    };
    shortExtensionOverride = "I enjoyed hearing how old photographs connected to places she had known since childhood, which helped me see local history as part of her own life.";
  } else if (/grow vegetables/.test(prompt)) {
    extensionOverride = {
      past: "She says the best part is picking ingredients just before cooking, so very little goes to waste. Her balcony is small, but she has found a use for each sunny corner. She sometimes sends me home with fresh herbs, and it has made me consider trying a pot of basil myself.",
    };
  } else if (/movie.*watched and enjoyed recently|movie.*enjoyed.*recently/.test(prompt)) {
    extensionOverride = {
      past: "One reason it stayed with me is that it connects a huge disaster with ordinary family choices. The futuristic setting is imaginative, but the characters' fear and loyalty felt familiar. I would watch it again because it balances large-scale action with relationships that give the story emotional weight.",
    };
  } else if (/important river|important.*lake/.test(prompt)) {
    extensionOverride = {
      past: "The trip also made me notice how closely the river connects transport, local livelihoods and history. I would like to visit another section because its landscape and role may be different from what I saw near Wuhan. That would help me understand it as a national feature rather than only one impressive view.",
    };
  } else if (/time you made an important decision and were happy with the result/i.test(prompt)) {
    extensionOverride = {
      past: "The useful part was learning that I could enter an unfamiliar group by contributing to a task. I still choose activities carefully so they do not interfere with study, but I am less likely to turn something down simply because I feel nervous. The decision changed how I approach new situations and helped university feel more connected.",
    };
  } else if (/important decision/.test(prompt)) {
    extensionOverride = {
      past: "I also learned to ask for advice when choosing a path, but leave the final decision to myself. A lecturer can explain the options, yet no one can predict exactly how a career will feel. I plan to keep experimenting through projects and review what I enjoy after graduation.",
    };
  } else if (/\badvertisement\b/.test(prompt)) {
    extensionOverride = {
      past: "Overall, I found the advert engaging because it showed the shoes in a normal setting rather than relying only on a famous face. The athlete made the brand familiar, but the clip left me wondering about durability. I felt interested, not ready to buy; I would want more information before deciding whether the shoes were worth the price.",
      future: "I would treat the celebrity's appearance as a way to notice the product, then check independent reviews and the details of its quality. An endorsement can make an advert memorable, but it does not prove the item is suitable for me.",
    };
    shortExtensionOverride = "I would remember the outdoor scene more than the celebrity's face because it made the product seem relevant to everyday exercise.";
  } else if (/\binterview(?:ed)?\b/.test(prompt)) {
    extensionOverride = {
      past: "What interested me was hearing the guest explain their work in their own words, rather than through a short headline. A pause or an unexpected question can reveal more about their priorities, although one interview is still only that person's perspective. I would look for another source before treating the conversation as a complete account. Later, I read one of his essays and noticed how carefully he shaped similar observations in a finished story.",
      future: "I would be curious to hear the guest explain their work in their own words and respond to an unexpected question. That might reveal more than a prepared speech, although I would still remember that one interview cannot represent a person's whole life or career.",
    };
  } else if (/important decision/.test(prompt)) {
    extensionOverride = {
      past: "The useful part was being able to test the choice in a real project before committing to a whole career. It made my strengths and gaps clearer and gave me specific skills to work on. I can still change direction later, but now I have a better-informed starting point.",
      future: "I would try the option on a small scale and ask people with relevant experience what the daily work is like. That would give me better evidence than guessing, while still leaving room to change direction as I learn more.",
    };
  }
  const extension = extensionOverride || partTwoExtensions[extensionIndex][1];
  const isFuture = /would like|want to|in the future|hope to|wish to/.test(prompt);
  const tense = isFuture ? "future" : /\bapp\b|program or app|computer program/.test(prompt) ? "present" : "past";
  const parts = [...story, extension[tense] || extension.past];
  let answer = parts.join(" ");
  if (countWords(answer) < 200) {
    const shortIndex = [5, 0, 1, 2, 3, 4, 5, 6][extensionIndex];
    const extra = partTwoShortExtensions[shortIndex][1];
    parts.push(shortExtensionOverride || extra[tense] || extra.past);
    answer = parts.join(" ");
  }
  if (countWords(answer) < 200) {
    parts.push(isFuture
      ? "Those practical details are what make the idea appealing to me."
      : "Those small details are what made the experience memorable for me.");
    answer = parts.join(" ");
  }
  if (countWords(answer) < 200) {
    parts.push("That is the detail I would mention if someone asked me about it later.");
    answer = parts.join(" ");
  }
  return answer;
}

